# Declarative: describe the end state, compute the steps from a diff.
def plan(desired, real):
    steps = []
    for name, size in desired.items():
        if name not in real:
            steps.append(("create", name, size))
        elif real[name] != size:
            steps.append(("update", name, size))
    for name in real:
        if name not in desired:
            steps.append(("destroy", name, real[name]))
    return steps

def apply(steps, real):
    for op, name, size in steps:   # execute the plan
        if op == "destroy":
            del real[name]
        else:
            real[name] = size

desired = {"web-1": "t3.micro", "web-2": "t3.micro"}
real = {"web-1": "t3.small", "old-1": "t3.micro"}
print("desired:", desired)
print("real   :", real)
for run in (1, 2):
    steps = plan(desired, real)
    print("run", run, "plan:", steps if steps else "no changes")
    apply(steps, real)
print("final  :", real)
# plan is O(N) in resources, space O(N)

# Lost update: two runs read the same state version, last writer wins.
def run(locking):
    store = {"state": {"vm": 1}}          # the remote state file
    lock = {"holder": None}

    def read(who):
        return dict(store["state"])

    def write(who, new_state):
        store["state"] = new_state

    a_view = read("A")                    # both read the same version
    if locking:
        lock["holder"] = "A"              # A holds the lock
    b_blocked = locking and lock["holder"] is not None
    a_view["bucket"] = 1                  # A's apply creates a bucket
    write("A", a_view)
    if b_blocked:
        print("  B waits for the lock, then re-reads state")
        b_view = read("B")
    else:
        b_view = {"vm": 1}                # B works from its stale copy
    b_view["queue"] = 1                   # B's apply creates a queue
    write("B", b_view)
    return store["state"]

print("without lock:", run(False), "<- bucket lost (orphaned)")
print("with lock   :", run(True))
# lock turns a read-modify-write race into a sequence: O(1) extra cost

# count addresses by index, for_each by key: remove "b" and compare.
def diff(old, new):
    out = []
    for addr in sorted(set(old) | set(new)):
        if addr not in new:
            out.append("destroy " + str(addr) + " (" + old[addr] + ")")
        elif addr not in old:
            out.append("create " + str(addr))
        elif old[addr] != new[addr]:
            out.append("change " + str(addr) + ": " + old[addr] + " -> " + new[addr])
    return out

names_before = ["a", "b", "c"]
names_after = ["a", "c"]                      # remove "b"
print("names:", names_before, "->", names_after)

# count: addresses are indexes 0,1,2
old_c = {i: n for i, n in enumerate(names_before)}
new_c = {i: n for i, n in enumerate(names_after)}
print("count:")
for line in diff(old_c, new_c):
    print("  ", line)

# for_each: addresses are the names themselves
old_f = {n: n for n in names_before}
new_f = {n: n for n in names_after}
print("for_each:")
for line in diff(old_f, new_f):
    print("  ", line)
# diff is O(N log N) because of the sort

# Drift: compare code, state and real world; decide per attribute.
code  = {"sg": {"ssh_open": False, "timeout": 30}, "tags": {"owner": "team"}}
state = {"sg": {"ssh_open": False, "timeout": 30}, "tags": {"owner": "team"}}
real  = {"sg": {"ssh_open": True,  "timeout": 60}, "tags": {"owner": "team", "cost": "x"}}
ignore = {("tags", "cost")}          # another tool owns this tag

drift = []
for res in real:
    for attr in real[res]:
        if (res, attr) in ignore:
            continue
        if state[res].get(attr) != real[res][attr]:
            drift.append((res, attr, state[res].get(attr), real[res][attr]))

for res, attr, was, now in drift:
    print("drift:", res + "." + attr, was, "->", now)
print("exit code:", 2 if drift else 0)   # like plan -detailed-exitcode
print("decision: revert ssh_open (wrong), adopt timeout 60 into code")
# O(R*A) time over resources and attributes
